const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s),keys=new Set();
let state='ready',score=0,best=0,wave=1,lives=3,player={x:480},aliens=[],shots=[],bombs=[],particles=[],barriers=[],dir=1,fireTimer=0,bombTimer=0,invuln=0,last=0,sound=false,audio;
try{best=Number(localStorage.getItem('starfall-best'))||0}catch{}
const stars=Array.from({length:100},()=>({x:Math.random()*960,y:Math.random()*520,s:Math.random()*1.5+.3}));
const sprites=[['00100100','00011000','00111100','01111110','11011011','11111111','00100100','01011010'],['00011000','01111110','11011011','11111111','00111100','01011010','10000001'],['00111100','01111110','11011011','11111111','00100100','01011010','10000001']];
function tone(f,d=.06){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=f;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
function hud(){$('#score').textContent=String(score).padStart(6,'0');$('#best').textContent=String(best).padStart(6,'0');$('#wave').textContent=String(wave).padStart(2,'0');$('#lives').textContent='◆ '.repeat(Math.max(0,lives))||'—'}
function formation(){aliens=[];for(let r=0;r<4;r++)for(let c=0;c<10;c++)aliens.push({x:140+c*65,y:65+r*48,r});dir=1;bombTimer=1;shots=[];bombs=[];barriers=[];for(let b=0;b<4;b++)for(let y=0;y<4;y++)for(let x=0;x<9;x++)if(!(y>1&&x>2&&x<6))barriers.push({x:155+b*195+x*7,y:403+y*7});}
function launch(){score=0;lives=3;wave=1;player={x:480};invuln=1;fireTimer=0;particles=[];formation();state='playing';$('#overlay').style.display='none';$('#pause').style.display='block';$('#status').textContent='MISSION ACTIVE';hud();tone(500,.15)}
function overlay(title,msg,label){$('#title').textContent=title;$('#message').textContent=msg;$('#start').textContent=label+' ↗';$('#overlay').style.display='flex'}
function pause(){if(state==='playing'){state='paused';overlay('TAKE A BREATHER.','Your sector can wait a moment.','RESUME MISSION');$('#status').textContent='MISSION PAUSED'}else if(state==='paused'){state='playing';$('#overlay').style.display='none';$('#status').textContent='MISSION ACTIVE'}}
function end(){state='over';$('#pause').style.display='none';overlay('SIGNAL LOST.','Final score: '+score+' · Wave '+wave+' reached.','TRY AGAIN');$('#status').textContent='MISSION ENDED';tone(80,.4)}
function burst(x,y,color){for(let i=0;i<15;i++)particles.push({x,y,vx:(Math.random()-.5)*180,vy:(Math.random()-.5)*180,life:.5,color})}
function update(dt){if(state!=='playing')return;player.x=Math.max(25,Math.min(935,player.x+((keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0))*370*dt));fireTimer-=dt;invuln-=dt;if(keys.has('Space')&&fireTimer<=0){shots.push({x:player.x,y:466});fireTimer=.19;tone(700,.04)}
let edge=false;for(const a of aliens){a.x+=dir*(25+wave*9+(40-aliens.length)*1.65)*dt;if(a.x<28||a.x>932)edge=true}if(edge){dir*=-1;for(const a of aliens){a.x=Math.max(28,Math.min(932,a.x));a.y+=20}}
bombTimer-=dt;if(bombTimer<=0&&aliens.length){const a=aliens[Math.floor(Math.random()*aliens.length)];bombs.push({x:a.x,y:a.y+15});bombTimer=Math.max(.2,.9-wave*.07)}
for(const s of shots)s.y-=530*dt;for(const b of bombs)b.y+=(160+wave*16)*dt;
for(const s of shots){if(s.y<0)continue;const i=aliens.findIndex(a=>Math.abs(s.x-a.x)<19&&Math.abs(s.y-a.y)<15);if(i>=0){const a=aliens.splice(i,1)[0];s.y=-100;score+=(4-a.r)*10;burst(a.x,a.y,a.r<2?'#d8ff6c':'#73d9c7');tone(180,.07);if(score>best){best=score;try{localStorage.setItem('starfall-best',best)}catch{}}hud()}}
for(const b of [...shots,...bombs]){if(b.y<0||b.y>520)continue;const i=barriers.findIndex(t=>Math.abs(b.x-(t.x+3))<8&&Math.abs(b.y-(t.y+3))<8);if(i>=0){barriers.splice(i,1);b.y=-100}}
for(const b of bombs)if(b.y>0&&invuln<=0&&Math.abs(b.x-player.x)<22&&Math.abs(b.y-477)<15){b.y=600;lives--;invuln=1.8;burst(player.x,477,'#ff8b83');hud();tone(100,.2);if(lives<=0){end();return}}
shots=shots.filter(s=>s.y>0);bombs=bombs.filter(b=>b.y>0&&b.y<530);if(aliens.some(a=>a.y>450)){end();return}if(!aliens.length){wave++;lives=Math.min(3,lives+1);formation();invuln=2;hud();tone(900,.25)}}
function alien(a,t){ctx.fillStyle=a.r<2?'#d8ff6c':'#73d9c7';const pattern=sprites[a.r%3];for(let y=0;y<pattern.length;y++)for(let x=0;x<8;x++)if(pattern[y][x]==='1')ctx.fillRect(a.x-16+x*4,a.y-14+y*4,3,3);if(Math.floor(t/500)%2){ctx.fillRect(a.x-20,a.y+8,4,8);ctx.fillRect(a.x+16,a.y+8,4,8)}}
function draw(t,dt){ctx.fillStyle='#080e0e';ctx.fillRect(0,0,960,520);for(const s of stars){s.y+=s.s*dt*8;if(s.y>520)s.y=0;ctx.fillStyle=`rgba(172,205,181,${s.s/3})`;ctx.fillRect(s.x,s.y,s.s,s.s)}ctx.strokeStyle='#223224';ctx.setLineDash([3,8]);ctx.beginPath();ctx.moveTo(0,499);ctx.lineTo(960,499);ctx.stroke();ctx.setLineDash([]);
if(state==='ready'){for(let r=0;r<3;r++)for(let c=0;c<10;c++)alien({x:155+c*72,y:80+r*55,r},t)}else{for(const a of aliens)alien(a,t);ctx.fillStyle='#8ca875';for(const b of barriers)ctx.fillRect(b.x,b.y,6,6);ctx.fillStyle='#e6ff9e';for(const s of shots)ctx.fillRect(s.x-2,s.y,4,15);ctx.fillStyle='#ff9984';for(const b of bombs)ctx.fillRect(b.x-2,b.y,4,12)}
const px=player.x;if(state!=='over'&&(invuln<=0||Math.floor(t/90)%2===0)){ctx.fillStyle='#d8ff6c';ctx.beginPath();ctx.moveTo(px,456);ctx.lineTo(px+7,471);ctx.lineTo(px+22,479);ctx.lineTo(px+22,487);ctx.lineTo(px-22,487);ctx.lineTo(px-22,479);ctx.lineTo(px-7,471);ctx.closePath();ctx.fill();ctx.fillStyle='#0e291c';ctx.fillRect(px-3,473,6,9);ctx.fillStyle='#77c6ab';ctx.fillRect(px-10,488,5,5+Math.sin(t/70)*3);ctx.fillRect(px+5,488,5,5+Math.cos(t/70)*3)}
for(const p of particles){if(state==='playing'){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt}ctx.globalAlpha=Math.max(0,p.life*2);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0)}
function frame(t){const dt=Math.min((t-last)/1000,.035);last=t;update(dt);draw(t,dt);requestAnimationFrame(frame)}
$('#start').onclick=()=>state==='paused'?pause():launch();$('#pause').onclick=pause;$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent=sound?'SOUND ON':'SOUND OFF';$('#sound').setAttribute('aria-pressed',sound);tone(400)};
addEventListener('keydown',e=>{if(['Space','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys.add(e.code);if(!e.repeat&&e.code==='KeyP')pause();if(!e.repeat&&e.code==='Enter'&&e.target.tagName!=='BUTTON'){if(state==='paused')pause();else if(state!=='playing')launch()}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();if(state==='playing')pause()});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key)};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key)});hud();requestAnimationFrame(frame);
